#!/usr/bin/env python3
"""Generate NearFastVM/Ops.lean: the operation enumeration and the map from Wasm instructions."""
import pathlib
from ops import all_ops, I_BIN, I_REL, I_UN32, I_UN64

out = ["import Wasm.Syntax", "",
       "/-! Generated by `scripts/gen_ops.py`; do not edit. -/", "",
       "namespace NearFastVM", "",
       "/-- The operations of the flat instruction stream. -/",
       "inductive Op where"]
for o in all_ops():
    out.append(f"  | {o}")
out += ["deriving Inhabited, DecidableEq, Repr", ""]

def lean_name(o):
    return {"and": "and", "or": "or"}.get(o, o)

out += ["open Wasm in",
        "/-- The operation of a Wasm numeric instruction, if it has one of its own. -/",
        "def Op.ofNumeric? : Instr → Option Op"]
for w in ("i32", "i64"):
    out.append(f"  | .{w}_eqz => some .{w}_eqz")
    out.append(f"  | .{w}_binop op => some (match op with")
    for o in I_BIN:
        out.append(f"      | .{lean_name(o)} => .{w}_{o}")
    out.append("    )")
    out.append(f"  | .{w}_relop op => some (match op with")
    for o in I_REL:
        out.append(f"      | .{o} => .{w}_{o}")
    out.append("    )")
out.append("  | .i32_unop op => some (match op with")
for o in I_UN32:
    out.append(f"      | .{o} => .i32_{o}")
out.append("      | .extend32_s => .nop)")
out.append("  | .i64_unop op => some (match op with")
for o in I_UN64:
    out.append(f"      | .{o} => .i64_{o}")
out.append("      | .extend32_s => .i64_extend_i32_s)")
out += ["  | .cvt .i32_wrap_i64 => some .i32_wrap_i64",
        "  | .cvt .i64_extend_i32_s => some .i64_extend_i32_s",
        "  | .cvt .i64_extend_i32_u => some .i64_extend_i32_u",
        "  | .cvt .i32_reinterpret_f32 => some .nop",
        "  | .cvt .i64_reinterpret_f64 => some .nop",
        "  | .cvt .f32_reinterpret_i32 => some .nop",
        "  | .cvt .f64_reinterpret_i64 => some .nop",
        "  | _ => none", "", "end NearFastVM", ""]
pathlib.Path(__file__).resolve().parent.parent.joinpath("NearFastVM/Ops.lean").write_text("\n".join(out))
